diff --git a/demo/orders-api/src/db.ts b/demo/orders-api/src/db.ts
index fa3c0a9..8c10f60 100644
--- a/demo/orders-api/src/db.ts
+++ b/demo/orders-api/src/db.ts
@@ -39,5 +39,32 @@ export async function openDb(): Promise<PGlite> {

     ANALYZE;
+
+    CREATE MATERIALIZED VIEW top_customers_mv AS
+      SELECT c.id AS customer_id,
+             c.name,
+             sum(o.amount_cents)::int AS revenue_cents,
+             count(*)::int AS orders
+      FROM orders o
+      JOIN customers c ON c.id = o.customer_id
+      WHERE o.status = 'paid'
+        AND o.created_at > now() - interval '30 days'
+      GROUP BY c.id, c.name
+      ORDER BY revenue_cents DESC;
+
+    CREATE UNIQUE INDEX top_customers_mv_pk ON top_customers_mv (customer_id);
   `);
   return db;
 }
+
+// Refreshes the materialized view and returns a handle that can stop the loop.
+export function startRefresh(db: PGlite, intervalMs = 5_000): { stop: () => void } {
+  const id = setInterval(() => {
+    // CONCURRENTLY requires a unique index and lets reads continue during refresh.
+    db.exec("REFRESH MATERIALIZED VIEW CONCURRENTLY top_customers_mv;").catch(() => {
+      // Ignore transient errors (e.g. db closing during tests).
+    });
+  }, intervalMs);
+  // Don't block Node.js exit if the caller forgets to stop.
+  if (typeof id === "object" && "unref" in id) (id as NodeJS.Timeout).unref();
+  return { stop: () => clearInterval(id) };
+}
